.github/workflows/release.yml.content:
name: release
on:
  push: {branches: [main]}
  workflow_dispatch:
    inputs: {repair_tag: {required: false, type: string}}
permissions: {contents: read}
concurrency: {group: "hiroba-release-${{ github.repository }}", cancel-in-progress: false}
jobs:
  release:
    uses: 7K-Hiroba/workflows/.github/workflows/release.yml@ed7c4a964b8605f118cc24765a22e12eae616c98 # v1.1.0
    with: {root: ., repair_tag: "${{ inputs.repair_tag }}", app-id: "${{ vars.HIROBA_RELEASE_APP_ID }}"}
    secrets:
      release-private-key: "${{ secrets.HIROBA_RELEASE_PRIVATE_KEY }}"
    permissions: {contents: write, packages: write, id-token: write, attestations: write, actions: read, artifact-metadata: write}

