observability/tests/alloy/config.river.content:
// Real Alloy pipeline fixture. The integration runner replaces only the two
// endpoint placeholders with ephemeral CI container addresses.
prometheus.scrape "workflows_scaffold" {
	targets         = [{"__address__" = "__TARGET__", "job" = "matrix-app"}]
	scrape_interval = "1s"
	honor_labels    = true
	forward_to      = [prometheus.relabel.central.receiver]
}

prometheus.relabel "central" {
	rule {
		target_label = "org"
		replacement  = "ci"
	}

	rule {
		target_label = "cluster"
		replacement  = "kind-ci"
	}
	forward_to = [prometheus.remote_write.central.receiver]
}

prometheus.remote_write "central" {
	endpoint {
		url = "__REMOTE_WRITE_URL__"
	}
}

release-please-config.json.content:
{
  "$schema": "https://raw.githubusercontent.com/googleapis/release-please/main/schemas/config.json",
  "separate-pull-requests": false,
  "include-component-in-tag": true,
  "include-v-in-tag": true,
  "tag-separator": "-v",
  "pull-request-title-pattern": "chore: release ${component} ${version}",
  "packages": {
    "templates/matrix-app": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "template.yaml"
      ],
      "component": "template-matrix-app"
    },
    "tests/smoke": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "suite.yaml"
      ],
      "component": "smoke-matrix-app-smoke"
    },
    "packages/observability-pack": {
      "release-type": "simple",
      "changelog-path": "CHANGELOG.md",
      "bump-minor-pre-major": true,
      "bump-patch-for-minor-pre-major": true,
      "extra-files": [
        "package.yaml"
      ],
      "component": "package-observability-pack"
    }
  }
}

renovate.json.content:
{
  "$schema": "https://docs.renovatebot.com/renovate-schema.json",
  "extends": ["config:recommended"],
  "pinDigests": true,
  "packageRules": [
    {
      "description": "Review trusted workflow SHAs and action updates manually",
      "matchManagers": ["github-actions"],
      "automerge": false
    },
    {
      "description": "Group reviewed non-major SDK and chart dependency updates",
      "matchUpdateTypes": ["minor", "patch", "digest", "pinDigest"],
      "groupName": "non-major dependencies",
      "automerge": false
    }
  ]
}
